import React from "react";
import { useParams } from "react-router-dom";
import products from "../data/products";
import { useCart } from "../context/CartContext";

const ProductDetail = () => {
  const { id } = useParams();
  const { addToCart } = useCart();

  const product = products.find((p) => p.id === parseInt(id));

  if (!product) return <h2 style={{ textAlign: "center" }}>Product Not Found</h2>;

  return (
    <div
      style={{
        padding: "50px",
        minHeight: "100vh",
        background: "#fff8fb",
      }}
    >
      <div
        style={{
          maxWidth: "1000px",
          margin: "auto",
          display: "flex",
          gap: "50px",
          flexWrap: "wrap",
          alignItems: "center",
          background: "white",
          padding: "30px",
          borderRadius: "25px",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
        }}
      >
        {/* IMAGE */}
        <div style={{ flex: "1" }}>
          <img
            src={product.image}
            alt={product.name}
            style={{
              width: "100%",
              borderRadius: "20px",
            }}
          />
        </div>

        {/* DETAILS */}
        <div style={{ flex: "1" }}>
          <h1 style={{ color: "#d63384" }}>{product.name}</h1>

          <p style={{ fontSize: "20px", margin: "10px 0" }}>
            Price: <strong>₹{product.price}</strong>
          </p>

          <p style={{ color: "#666" }}>
            Age: {product.age || "Not specified"}
          </p>

          <p style={{ marginTop: "20px", lineHeight: "1.6" }}>
            This beautiful handmade product is made with love 💖.
            Perfect for your little one. Soft, comfortable and stylish.
          </p>

          <button
            onClick={() => addToCart(product)}
            style={{
              marginTop: "25px",
              padding: "12px 25px",
              border: "none",
              borderRadius: "25px",
              background: "#ff4f87",
              color: "white",
              fontSize: "16px",
              cursor: "pointer",
            }}
          >
            Add to Cart 🛒
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
